miete_rueckstandsbetragsgrenze <- function(regelfall=NULL, massgebliche_monatsmiete=NULL, qualifizierter_rueckstand=NULL, einordnungsnachweis=NULL) {
 faelle <- list(wohnraum_zwei_aufeinanderfolgende_termine=list(1,TRUE,"\u00a7543II1Nr3a iVm569III1: R\u00fcckstand f\u00fcr genau zwei unmittelbar aufeinanderfolgende Termine bei Wohnraum, der nicht nur zum vor\u00fcbergehenden Gebrauch vermietet ist; strikt mehr als eine ma\u00dfgebliche Monatsmiete. Terminzusammenhang und Verzug vorqualifiziert. F\u00fcr andere Mietarten keine erfundene feste Erheblichkeitsschwelle."),miete_mehr_als_zwei_termine=list(2,FALSE,"\u00a7543II1Nr3b: qualifizierter Verzugsr\u00fcckstand aus einem Zeitraum \u00fcber mehr als zwei Termine; mindestens zwei Monatsmieten. Der mehr als zwei Termine umfassende Zeitraum ist eine zus\u00e4tzlich vorqualifizierte Voraussetzung, keine blo\u00dfe Anzahl unbezahlter Raten."),wohnraum_sicherheitsleistung=list(2,FALSE,"\u00a7569IIa: qualifizierter Verzugsr\u00fcckstand mit der Sicherheitsleistung551; mindestens zwei Monatsmieten OHNE als Pauschale oder Vorauszahlung ausgewiesene Betriebskosten. Nur f\u00e4llige, geschuldete Sicherheitsleistung erfassen; Ratenrecht551II beachten, keine gesamte noch nicht f\u00e4llige Kaution."))
 .auswahl(regelfall,'regelfall',names(faelle))
 miete <- .geld(massgebliche_monatsmiete);rueckstand <- .geld(qualifizierter_rueckstand)
 if(.vergleichen(miete,.bruch(0))<=0) .fehler('massgebliche_monatsmiete','Positive Bezugsmonatsmiete erforderlich.')
 .text(einordnungsnachweis,'einordnungsnachweis')
 f <- faelle[[regelfall]];grenze <- .multiplizieren(miete,.bruch(f[[1]]));vergleich <- .vergleichen(rueckstand,grenze)
 wert <- list(betragsgrenze=.bruchteile(grenze),vergleichsoperator=if(f[[2]]) '>' else '>=',rueckstand_abzueglich_grenze=.bruchteile(.subtrahieren(rueckstand,grenze)),betragsvoraussetzung_erfuellt=if(f[[2]]) vergleich>0 else vergleich>=0)
 eingaben <- list(regelfall=regelfall, massgebliche_monatsmiete=massgebliche_monatsmiete, qualifizierter_rueckstand=qualifizierter_rueckstand, einordnungsnachweis=einordnungsnachweis)
 ergebnis <- .ergebnis(wert,"EUR_und_wahrheitswert","BGB_MIETE_RUECKSTANDSBETRAGSGRENZE",eingaben,list(list(operation="Qualifizierten Verzugsr\u00fcckstand mit einer beziehungsweise zwei Monatsmieten vergleichen; strikte und einschlie\u00dflich geltende Grenzen unterscheiden.")),eingaben)
 ergebnis$hinweise <- list("Nur betragsm\u00e4\u00dfige Teilgrenze, kein K\u00fcndigungsentscheid. Ma\u00dfgebliche Monatsmiete und R\u00fcckstandsbestand zum Pr\u00fcfzeitpunkt rechtlich bestimmen, insbesondere Mietminderung, Betriebskostenabgrenzung, Zahlungszuordnung und Miet\u00e4nderungen. Verzug, Frist-/Terminzusammenhang, Anwendungsbereich und Wirksamkeit der K\u00fcndigung gesondert; vorherige Befriedigung, Aufrechnung und Schonfristheilung werden nicht aus dem Zahlenvergleich abgeleitet. F\u00fcr die Kautionsgrenze Betriebskosten ausschlie\u00dfen; diese Nettobasis nicht pauschal auf Mietr\u00fcckst\u00e4nde \u00fcbertragen.",f[[3]])
 ergebnis
}
